// Monta o pedido ao Gemini para o relatório da R.I. Os números vêm prontos do portal; a IA só escreve.
const t = $json;
const d = (t.payload || {}).dados || {};
const enxuto = (i) => i && ({
  resumo: i.resumo, coldcall: i.coldcall, funil: i.funil,
  tempoPorFase: (i.tempoPorFase || []).map((f) => ({ fase: f.fase, sla: f.sla, mediaDias: f.mediaDias, dentroSla: f.dentroSla })),
  motivosPerda: i.motivosPerda, motivosDesqualificacao: i.motivosDesqualificacao, origens: i.origens,
});
const numeros = {
  periodo: d.periodo, semana: enxuto(d.semana), trimestre: enxuto(d.trimestre),
  membros: (d.membros || []).map((m) => ({
    nome: m.nome, cargo: m.cargo, semana: m.semana, trimestre: m.trimestre,
    ligacoes_semana: m.ligacoes_semana && { ligacoes: m.ligacoes_semana.ligacoes, pctDiagnostico: m.ligacoes_semana.pctDiagnostico, porResultado: m.ligacoes_semana.porResultado },
    tarefas_atrasadas: m.tarefas_atrasadas, negocios_ativos: m.negocios_ativos,
  })),
  sla_estourado: d.sla_estourado,
};
const prompt = [
  'Você é o Analista gerencial da Diretoria Comercial da Aprimora (empresa júnior de consultoria).',
  'Escreva a análise da Reunião de Indicadores (R.I) a partir dos números abaixo, que já estão calculados e são a fonte da verdade.',
  'Regras: português do Brasil, frases curtas e diretas; cite números exatamente como estão; não invente dados; taxas vêm de 0 a 1 (0,25 = 25%);',
  'valores em reais; compare semana com trimestre quando ajudar; o plano de cada membro é um rascunho que o diretor vai revisar,',
  'então seja específico e acionável (ex.: "subir de 12 para 20 ligações por semana"). Inclua um plano para cada membro listado.',
  '',
  'Números:',
  JSON.stringify(numeros),
].join('\n');
const lista = { type: 'ARRAY', items: { type: 'STRING' } };
return {
  json: {
    trabalho: { id: t.id },
    corpo: {
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      generationConfig: {
        temperature: 0.3,
        responseMimeType: 'application/json',
        responseSchema: {
          type: 'OBJECT',
          properties: {
            resumo: { type: 'STRING' },
            destaques: lista,
            pontos_atencao: lista,
            planos: {
              type: 'ARRAY',
              items: {
                type: 'OBJECT',
                properties: { membro: { type: 'STRING' }, pontos_fortes: lista, melhorias: lista, acoes: lista },
                required: ['membro', 'pontos_fortes', 'melhorias', 'acoes'],
              },
            },
          },
          required: ['resumo', 'destaques', 'pontos_atencao', 'planos'],
        },
      },
    },
  },
};

// Lê a análise (JSON garantido pelo responseSchema) e devolve ao portal.
const trabalho = $('Montar pedido').item.json.trabalho;
const c = ($json.candidates || [])[0] || {};
const texto = ((c.content || {}).parts || []).map((p) => p.text || '').join('').trim();
if (!texto) throw new Error('Gemini respondeu sem texto (' + (c.finishReason || 'sem motivo') + ')');
let analise;
try {
  analise = JSON.parse(texto);
} catch (err) {
  throw new Error('JSON inválido do Gemini: ' + err.message);
}
return { json: { trabalho_id: trabalho.id, resultado: { analise } } };
